import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Rhino.html","title":"Rhino","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.65,"words":496},"filePathRelative":"Rhino.md"}`),a={name:`Rhino.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="rhino" tabindex="-1"><a class="header-anchor" href="#rhino"><span>Rhino</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a></p><p><a href="./JavaScript.html">JavaScript</a>インタープリタのJavaによる実装。Mozilla製。Androidでもインタープリタモードなら動きそう。<a href="./EmbeddedLang.html">EmbeddedLang</a></p><ul><li><a href="https://github.com/mozilla/rhino/tree/master" target="_blank" rel="noopener noreferrer">mozilla/rhino: Rhino is an open-source implementation of JavaScript written entirely in Java</a> 公式 <ul><li><a href="https://github.com/mozilla/rhino/blob/master/it-android/README.md" target="_blank" rel="noopener noreferrer">rhino/it-android/README.md at master · mozilla/rhino</a> 公式でAndroidのテストが入っている</li></ul></li><li><a href="https://mozilla.github.io/rhino/compat/engines.html" target="_blank" rel="noopener noreferrer">Rhino ES2015/ES6, ES2016 and ES2017 support</a> サポート状況 <ul><li>async-awaitは無いっぽい <a href="https://github.com/mozilla/rhino/issues/395" target="_blank" rel="noopener noreferrer">Support ES2017 async (arrow) functions &amp; “await” · Issue #395 · mozilla/rhino</a></li><li>arrow関数はあるか</li></ul></li><li><a href="https://github.com/mozilla/rhino/blob/96d264acd2df85ad685ecdc4f059b4413f99faeb/rhino/src/test/java/org/mozilla/javascript/tests/ContinuationsApiTest.java#L37" target="_blank" rel="noopener noreferrer">rhino/rhino/src/test/java/org/mozilla/javascript/tests/ContinuationsApiTest.java at 96d264acd2df85ad685ecdc4f059b4413f99faeb · mozilla/rhino</a> 中断はできそう。</li><li><a href="https://github.com/ShabdVasudeva/OneUI-Gallery-Clone" target="_blank" rel="noopener noreferrer">ShabdVasudeva/OneUI-Gallery-Clone</a> Androidで使ってるアプリで現在でも動きそうなもの</li><li><a href="https://github.com/oracle/graaljs" target="_blank" rel="noopener noreferrer">oracle/graaljs: GraalJS – A high-performance, ECMAScript compliant, and embeddable JavaScript runtime for Java</a> GraalJSはRhinoより新しいJSで動くとの事でESMとかもサポートしているらしくAndroidでも動くと言っているが、良くわからん。</li></ul><p>使ってみたらあっさり動いて中断とか再開も出来るので気にった。使っていこう＞<a href="./AshX.html">AshX</a>, <a href="./Rhinocs.html">Rhinocs</a></p><h2 id="objectリテラルのメソッド-は使える" tabindex="-1"><a class="header-anchor" href="#objectリテラルのメソッド-は使える"><span>Objectリテラルのメソッド（は使える）</span></a></h2><p>昔ながらのprototypeとか書いていて、シングルトンはこんな事する必要無いよなぁ、とCopilotにオブジェクトリテラルに直してもらったら、 アロー関数のthisは呼び出しもとだ、とか言われて、method定義に直された。</p><p>あれ？Rhinoってメソッド使えたっけ？と調べると使える＞<a href="https://mozilla.github.io/rhino/compat/engines.html#ES2015-syntax-object-literal-extensions-shorthand-methods" target="_blank" rel="noopener noreferrer">Rhino ES2015/ES6, ES2016 and ES2017 support</a></p><p>なおclassキーワードは使えない。asyncは使えないがgeneratorは使えたり、何が使えるかちょっと曖昧だよなぁ。</p><p>でもObjectのメソッドはもう使えない環境は無さそうだから積極的に使っていった方がいいな。</p><h2 id="javascriptの配列をjavaから使う" tabindex="-1"><a class="header-anchor" href="#javascriptの配列をjavaから使う"><span>JavaScriptの配列をJavaから使う</span></a></h2><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">select_file_callback</span><span class="token punctuation">(</span><span class="token punctuation">[</span>mimeType<span class="token punctuation">]</span><span class="token punctuation">,</span> onSuccess<span class="token punctuation">,</span> onFailure<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>という関数を作った時に、Java側で最初のmimeTypesの配列をどう扱ったらいいかわからなかったので調べた。 Scriptableにキャストしてctx.getElementsでObjectの配列が取れる。</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code class="language-java"><span class="line">        <span class="token class-name">Object</span><span class="token punctuation">[</span><span class="token punctuation">]</span> mtypesObj <span class="token operator">=</span> ctx<span class="token punctuation">.</span><span class="token function">getElements</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">Scriptable</span><span class="token punctuation">)</span>args<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>中身は <code>ctx.toString(mTypesObj[0])</code> とかする必要がある。</p><h2 id="for-ofのconstは対応していない" tabindex="-1"><a class="header-anchor" href="#for-ofのconstは対応していない"><span>for ofのconstは対応していない</span></a></h2><p>for ofは対応しているしconstも対応しているが、以下は対応していない。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">for</span><span class="token punctuation">(</span><span class="token keyword">const</span> a <span class="token keyword">of</span> arr<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token operator">...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なお、letは動く。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">for</span><span class="token punctuation">(</span><span class="token keyword">let</span> a <span class="token keyword">of</span> arr<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token operator">...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ちなみに以下のgはzzzになる。(letにかえるとzbccになる)。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> arr <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&quot;a&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;b&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;c&quot;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> g <span class="token operator">=</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">for</span><span class="token punctuation">(</span><span class="token keyword">let</span> <span class="token punctuation">[</span>index<span class="token punctuation">,</span> elem<span class="token punctuation">]</span> <span class="token keyword">of</span> arr<span class="token punctuation">.</span><span class="token function">entries</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> item <span class="token operator">=</span> index <span class="token operator">===</span> <span class="token number">0</span> <span class="token operator">?</span> <span class="token string">&#39;z&#39;</span> <span class="token operator">:</span> elem<span class="token punctuation">.</span><span class="token function">repeat</span><span class="token punctuation">(</span>index<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  g <span class="token operator">=</span> g <span class="token operator">+</span> item<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>わ、わかりにくい…</p><h2 id="spreadは未対応" tabindex="-1"><a class="header-anchor" href="#spreadは未対応"><span>spreadは未対応</span></a></h2><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">hoge</span><span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>res</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">ika</span><span class="token punctuation">(</span><span class="token operator">...</span>res<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &lt;- シンタックスエラー</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なお、applyは使えるので以下は動く。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">hoge</span><span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>res</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">ika</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">,</span> res<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="docstringのメモ" tabindex="-1"><a class="header-anchor" href="#docstringのメモ"><span>docstringのメモ</span></a></h2><p>describe-function的なものを実装するために、なんかdocstringみたいなの無い？とgeminiに聞いたら以下を教えてくれたので貼っておく。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">getDocstring</span><span class="token punctuation">(</span><span class="token parameter">fn</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">var</span> fnSource <span class="token operator">=</span> fn<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 関数の最初にある /** ... */ または /* ... */ のブロックコメントを抽出する正規表現</span></span>
<span class="line">    <span class="token keyword">var</span> match <span class="token operator">=</span> fnSource<span class="token punctuation">.</span><span class="token function">match</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^function\\s*.*?\\s*\\(\\s*.*?\\s*\\)\\s*\\{\\s*(\\/\\*\\*[\\s\\S]*?\\*\\/|\\/\\*[\\s\\S]*?\\*\\/)</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>match <span class="token operator">&amp;&amp;</span> match<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// コメント内のアスタリスクや無駄な改行を綺麗に掃除する</span></span>
<span class="line">        <span class="token keyword">return</span> match<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^\\/\\*\\*|^\\/\\*|\\*\\/$</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span> <span class="token comment">// デリミタの削除</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^\\s*\\*\\s?</span><span class="token regex-delimiter">/</span><span class="token regex-flags">mg</span></span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span>          <span class="token comment">// 行頭の「 * 」の削除</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// --- 使い方 ---</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">myAppFunction</span><span class="token punctuation">(</span><span class="token parameter">x<span class="token punctuation">,</span> y</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token doc-comment comment">/**</span>
<span class="line">     * 2つの数値を加算する関数です。</span>
<span class="line">     * <span class="token keyword">@param</span> <span class="token class-name"><span class="token punctuation">{</span>number<span class="token punctuation">}</span></span> <span class="token parameter">x</span> - 最初の数値</span>
<span class="line">     * <span class="token keyword">@param</span> <span class="token class-name"><span class="token punctuation">{</span>number<span class="token punctuation">}</span></span> <span class="token parameter">y</span> - 2番目の数値</span>
<span class="line">     * <span class="token keyword">@returns</span> <span class="token class-name"><span class="token punctuation">{</span>number<span class="token punctuation">}</span></span> 計算結果</span>
<span class="line">     */</span></span>
<span class="line">    <span class="token keyword">return</span> x <span class="token operator">+</span> y<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">var</span> doc <span class="token operator">=</span> <span class="token function">getDocstring</span><span class="token punctuation">(</span>myAppFunction<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">print</span><span class="token punctuation">(</span>doc<span class="token punctuation">)</span><span class="token punctuation">;</span> </span>
<span class="line"><span class="token comment">// 出力:</span></span>
<span class="line"><span class="token comment">// 2つの数値を加算する関数です。</span></span>
<span class="line"><span class="token comment">// @param {number} x - 最初の数値</span></span>
<span class="line"><span class="token comment">// @param {number} y - 2番目の数値</span></span>
<span class="line"><span class="token comment">// @returns {number} 計算結果</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};